def evidence(p, kind='artifact', label=None):
    p=Path(p).resolve(); return {'id':label or 'e-'+sha(p)[:14], 'kind':kind,'path':str(p),'sha256':sha(p)}
def dt(x): return datetime.datetime.strptime(x['current_time'],'%Y-%m-%d %H:%M:%S UTC')
def ops(arm):
    x=load(BASE/'observations'/f'{arm}.json'); start=x['before_spawn']; turns=[]
    if arm.startswith(('code-','data-')):
        end=x.get('terminal_observed_at',x.get('terminal_recorded_at')); calls=2; actors=2; failed=0; followups=0
        turns=[{'actor':x['spawn_result']['task_name'],'operation':'spawn_agent','start':start,'end':end},{'role':'independent reviewer','operation':'spawn_agent','timing':'Not exact; observed lifecycle snapshots retained in outer arm file and journal.'}]
    elif arm.startswith(('creative-','recovery-')):
        end=x['final_integration_resume']['terminal_observed_at']; calls=5; actors=2; failed=1; followups=3
        turns=[{'actor':x['spawn_result']['task_name'],'operation':'spawn_agent','start':start,'end':x['first_turn_terminal_observed_at']}, x['outer_review_attempt'], x['repair_resume'],x['recheck_resume'],x['final_integration_resume']]
    else:
        end=x['coordinator_resumes'][-1]['terminal_observed_at']; calls=1+len(x['role_observations'])+len(x['coordinator_resumes']); actors=4; failed=1; followups=9
        turns=[{'actor':x['spawn_result']['task_name'],'operation':'spawn_agent','start':start,'end':x['first_turn_terminal_observed_at']},*x['role_observations'],*x['coordinator_resumes']]
    workers=[]
    if arm.startswith('promotion'):
        workers=[{'role':r['role'],'requested_model':r['requested_model'],'requested_effort':r['requested_effort'],'effective_model':None,'effective_effort':None} for r in x['role_observations'][:3]]
    else: workers=[{'role':'independent review','requested_model':'gpt-6-astra' if arm.endswith('baseline') else 'gpt-5.6-sol','requested_effort':'xhigh','effective_model':None,'effective_effort':None}]
    return {'arm':arm,'actor_calls':calls,'distinct_actors':actors,'successful_initial_spawns':actors,'followup_calls':followups,'failed_dispatch_attempts':failed,'total_dispatch_and_followup_attempts':calls+failed,'started_at':start['current_time'],'finished_at':end['current_time'],'wall_seconds':(dt(end)-dt(start)).total_seconds(),'scope':'Outer pre-dispatch clock through final terminal observation; includes recording latency, coordination, reviewer time, repairs and gaps; not model compute or money. Native completion exit code unknown. Successful actor invocations include followups; failed dispatches separately counted. Evaluator/setup/scorer invocations excluded.','turns':turns,'workers':workers,'reported_tokens':None,'reported_money':None}

