def arm_sources(arm):
    a=ARMS/arm
    paths=[a/'prompt.txt',a/'checks.json',a/'evidence/actor-journal.md',BASE/'observations'/f'{arm}.json',OUT/f'{arm}-checks.json',OUT/'integrity.json',OUT/'record-inspection.json',OUT/'reporting-checks.json']
    for d in ['work','inputs']:
        paths += [p for p in sorted((a/d).iterdir()) if p.is_file()]
    paths += [p for p in sorted((a/'evidence').iterdir()) if p.is_file() and p.suffix in ['.md','.txt','.json','.py','.jsonl','.mjs']]
    paths += list((a/'state').glob('**/events.jsonl'))+list((a/'state').glob('**/snapshot.json'))+list((a/'state').glob('**/report.md'))
    if arm=='creative-treatment': paths += [OUT/'browser-attempt-2/observations.json', OUT/'browser-attempt-2/viewport-1280x800.png',OUT/'browser-attempt-2/viewport-390x844.png',a/'evidence/browser-repair-main/viewport-1280x800.png',a/'evidence/browser-repair-main/viewport-390x844.png',a/'evidence/browser-repair-disabled/observations.json',a/'evidence/browser-repair-focus/observations.json',a/'evidence/browser-demonstration-1/observations.json']
    if arm=='promotion-treatment': paths += list((a/'state/knowledge').glob('**/*.json'))
    unique=list(dict.fromkeys(paths)); result=[]
    for p in unique:
        label='journal' if p==a/'evidence/actor-journal.md' else 'outer' if p==BASE/'observations'/f'{arm}.json' else 'checks' if p==OUT/f'{arm}-checks.json' else 'integrity' if p==OUT/'integrity.json' else 'record-inspection' if p==OUT/'record-inspection.json' else 'reporting' if p==OUT/'reporting-checks.json' else None
        e=evidence(p,'transcript' if label=='journal' else 'artifact',label)
        if label=='journal': e['provenance']='Actor-authored journal, NOT raw native transcript. Enum used only as required legacy container; actual lifecycle has separate outer evidence.'
        if label=='outer': e['provenance']='Normalized direct outer native request/lifecycle observations, NOT raw child transcript.'
        result.append(e)
    # Identical-byte files legitimately share a hash; evidence IDs must still be unique.
    for i,e in enumerate(result):
        if e['id'].startswith('e-'): e['id']=f'file-{i}'
    return result

def build_arm(arm):
    family=arm.split('-')[0]; op=ops(arm); ev=arm_sources(arm); dims=load(ARMS/arm/'checks.json')['dimensions']
    scores=dict(zip(COMMON,[9,9,8.5,8.5,8.5,9,7]))
    if family=='creative': scores.update(task_completeness=8.5,orchestration_behavior=7,artifact_experience=8.5)
    if family=='recovery': scores.update(evidence_quality=9,report_quality=9,recovery_behavior=9)
    if family=='promotion': scores.update(task_correctness=8.5,task_completeness=9,orchestration_behavior=9,knowledge_behavior=8.5)
    reason={
      'task_correctness':CHECKS[family][0][2] if family!='promotion' else CHECKS[family][2][2],
      'task_completeness':'All requested task deliverables and substantive checks are present; scope limitations are disclosed. This score does not compensate for separate reporting/orchestration failures.',
      'evidence_quality':'Independent checks corroborate artifacts and preserved sources. Authored journals and normalized outer observations are qualified; effective identity, usage and money remain null. Generated-report defect is scored under report_quality.',
      'orchestration_behavior':'Bounded coordinator work plus genuine independent review; original-task briefs exclude supplemental builder rationale, dependency order and release observations support single-writer transitions. Physical exclusivity is not proven by helper validation alone.',
      'routing_efficiency':'Requested review routing follows the frozen policy (Sol/xhigh treatment, Astra/xhigh baseline); coordinator work stays cohesive. All invocations, bookkeeping corrections and observation time are counted; no pricing/effective-placement claim.',
      'safety_reversibility':'Frozen inputs/installed files preserved, changes confined to arm scope, reviewers do not repair candidates, unknown effects not converted to completion; observed reversibility checks match case requirements.',
      'report_quality':'Tailored reports disclose results/limits, but the delivered generated report says Unknowns: None despite recorded unknowns (LIVE-02); this material contradiction prevents the reporting threshold.',
      'artifact_experience':CHECKS['creative'][3][2], 'recovery_behavior':CHECKS['recovery'][1][2], 'knowledge_behavior':CHECKS['promotion'][2][2]}
    if family=='creative': reason['orchestration_behavior']='Independent review and focused repair succeeded through outer dispatch and a continuation; the original admitted no-handle review remains unreconcilable under installed contract (LIVE-01). This is a durable orchestration weakness, not claimed active physical work.'
    if family=='promotion':
        reason['orchestration_behavior']='Three distinct actual role actors independently author/refute/review, initial reviewer dissent blocks landing, one original-author repair receives renewed challenge/review, coordinator owns all pointer changes after terminal releases.'
        reason['routing_efficiency']='Required four-role team uses Sol/high author, Astra/high refuter, Sol/xhigh reviewer and Astra/high coordinator. Thirteen successful invocations including nine followups plus one failed dispatch are counted; outer capacity workaround adds overhead, no spend inference.'
    if family=='recovery': reason['report_quality']='Final assessment and generated source report consistently distinguish complete assessment from open export source, preserve draft/effect unknowns and conditional future authority; one unsupported requested-routing sentence was independently repaired/rechecked.'
    refs=['checks','integrity','journal','outer','record-inspection']; scored={d:{'value':scores[d],'rationale':reason[d],'evidence_refs':refs+(['reporting'] if d in ['report_quality','orchestration_behavior'] else [])} for d in dims}
    checks=[{'id':i,'value':v,'outcome':'passed' if v>=8.5 else 'failed','rationale':r,'evidence_refs':refs+(['reporting'] if i=='live-procedure' else [])} for i,v,r in CHECKS[family]]
    errors=[i['id'] for i in ISSUES if arm in i['arms']]
    card={'schema_version':'sage-independent-live-scorecard-v1','arm':arm,'scorer':{'id':SCORER,'independent':True,'not_output_author':True,'requested_model':'gpt-6-astra','requested_effort':'high','effective_model':None,'effective_effort':None},'scores':scored,'checks':checks,'open_errors':errors,'gate':{'minimum_each':8.5,'zero_open_errors':True,'aggregate_compensation':False,'passed':not errors and all(v['value']>=8.5 for v in scored.values()) and all(x['outcome']=='passed' for x in checks)},'evidence':ev,'operational':op,'frozen_setup_manifest_sha256':load(SETUP/'setup-freeze.json')['manifest_sha256'],'non_applicable':load(ARMS/arm/'checks.json')['not_applicable']}
    save(f'{arm}-scorecard.json',card)
    ev=ev+[evidence(OUT/f'{arm}-scorecard.json','scorecard','scorecard')]
    return {'execution':{'status':'completed','exit_code':None,'exit_code_reason':'Native collaboration completion has no exposed OS exit code; verifier subprocess exit codes are in checks evidence and are not native status.','run_id':op['turns'][0]['actor'],'started_at':op['started_at'],'finished_at':op['finished_at'],'evidence':ev},'routing':{'root_model_requested':'gpt-6-astra','root_model_effective':None,'root_effort_requested':'high','root_effort_effective':None,'eligible_worker_policy':'astra_for_every_eligible_worker' if arm.endswith('baseline') else 'sage_routing','workers':op['workers']},'checks':checks,'scores':scored,'scorer':{'id':SCORER,'independent':True,'evidence_refs':['scorecard']},'actor_calls':op['actor_calls'],'wall_seconds':op['wall_seconds'],'operational_evidence_refs':['outer','journal','scorecard'],'reported_tokens':None,'reported_money':None,'open_errors':errors,'gate_passed':card['gate']['passed']}

def main():
    allarms={arm:build_arm(arm) for arm in ARMLIST}; fixed=load(SETUP/'frozen-pairs.json')
    pairs=[]
    for row,family in zip(fixed['pairs'],['code','data']):
        pairs.append({k:row[k] for k in ['case_id','order','case_binding_sha256']}|{'treatment':allarms[family+'-treatment'],'baseline':allarms[family+'-baseline']})
    save('paired-results.json',{'schema_version':'sage-live-native-scored-results-v1','frozen_manifest_sha256':fixed['manifest_sha256'],'pairs':pairs,'provenance':'Not raw transcripts; authored journals plus independently normalized outer observations and new scorer checks. Native exit_code remains null.'})
    sm=load(SETUP/'frozen-smokes.json'); smokes=[]
    for row,family in zip(sm['cases'],['creative','recovery','promotion']): smokes.append({'case_id':row['case_id'],'kind':row['kind'],'case_binding_sha256':canonical(row),'arm':'treatment','result':allarms[family+'-treatment']})
    save('smoke-results.json',{'schema_version':'sage-independent-smoke-results-v1','frozen_manifest_sha256':sm['manifest_sha256'],'cases':smokes})
    save('issues.json',{'issues':ISSUES,'root_candidate_assessment':{'note_enum':'Confirmed by omitted installed enum plus four paired atomic rejections; product documentation issue, not candidate arithmetic failure.','dispatch_failure':'Confirmed on exact copied creative run; native capacity is environment-specific, durable failure representation gap is product-level.','native_exit':'Confirmed by actual frozen validator rejection with honest null, not fixed or worked around.','architecture_message':'Root later reported architecture drift; explicitly outside this bounded scoring assessment and not scored here.'},'nonblocking_residuals':[{'id':'RES-01','summary':'Promotion discovery accepts absent/different environment cues after repair; semantic applicability remains explicitly Python/sample-bound in retrieved record. R-042 still requires the caller to honor text. No supported transfer claim observed.'},{'id':'RES-02','summary':'Creative original event points to subsequently repaired working path. Exact original bytes are retained under evidence/original-index.html and final report links their hash; navigation drift is not loss of evidence.'},{'id':'RES-03','summary':'Screen reader, runtime reduced motion, touch, exact demonstration transition timestamp and other platforms remain untested; source/keyboard evidence meets only the declared bounded smoke scope.'}],'environment_deviations':['Native thread-limit failure in each smoke, recovered through sequential outer role dispatch and followups; later smoke packets also received disclosed current-capacity environment note.','Creative unfiltered lifecycle response exposed unrelated completed-arm text; actor disclosed exposure, no use proved or disproved. Paired arms finished before this incident.','Owned headless browser requires sandbox escalation; restricted attempts retained.'],'whole_skill_gate':'Not assessed or passed by this scorer.'})
    validation_cmd=[sys.executable,str(BASE.parents[2]/'pairing.py'),'validate',str(OUT/'paired-results.json'),'--manifest',str(SETUP/'frozen-pairs.json')]
    # BASE is evaluation/sandboxes/live-evaluation, so evaluation is parents[1].
    validation_cmd[1]=str(BASE.parents[1]/'pairing.py')
    p=subprocess.run(validation_cmd,capture_output=True,text=True)
    save('paired-validation.json',{'command':validation_cmd,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'expected_honest_limitation':'Frozen native result cannot provide an OS exit code; do not substitute verifier exits.','schema_passed':p.returncode==0})
    validations=[]
    for arm,result in allarms.items():
        checks=load(ARMS/arm/'checks.json'); ev=result['execution']['evidence']; ids={e['id'] for e in ev}
        assert len(ids)==len(ev)
        assert set(result['scores'])==set(checks['dimensions'])
        assert [c['id'] for c in result['checks']]==[c['id'] for c in checks['checks']]
        for e in ev: assert sha(e['path'])==e['sha256']
        for s in list(result['scores'].values())+result['checks']: assert math.isfinite(s['value']) and 0<=s['value']<=10 and set(s['evidence_refs'])<=ids
        assert result['execution']['exit_code'] is None
        validations.append({'arm':arm,'hash_bound_evidence_count':len(ev),'scores_complete':True,'frozen_checks_complete':True,'hashes_match':True,'gate_passed':result['gate_passed']})
    save('score-validation.json',{'ok':True,'scope':'Scorer artifact/hash/applicability/score-reference completeness for all seven arms; not a replacement pass for frozen pairing.py.','arms':validations,'smoke_manifest_selfhash':canonical({k:v for k,v in sm.items() if k!='manifest_sha256'}),'expected_smoke_manifest_selfhash':sm['manifest_sha256']})
    save('smoke-validation.json',{'ok':True,'frozen_manifest_sha256':sm['manifest_sha256'],'validation_scope':'Unchanged smoke manifest and applicability, every frozen check and dimension scored with valid hashes/references; no claim of all smoke gates passing. Native exit code is null.','cases':[v for v in validations if v['arm'].split('-')[0] in ['creative','recovery','promotion']]})
    differences=[]
    for family in ['code','data']:
        t=allarms[family+'-treatment']; b=allarms[family+'-baseline']
        differences.append({'family':family,'treatment_minus_baseline_scores':{d:t['scores'][d]['value']-b['scores'][d]['value'] for d in t['scores']},'actor_call_difference':t['actor_calls']-b['actor_calls'],'outer_wall_seconds_difference':t['wall_seconds']-b['wall_seconds'],'treatment_gate':t['gate_passed'],'baseline_gate':b['gate_passed']})
    save('operational-results.json',{'arms':[ops(a) for a in ARMLIST],'paired_differences':differences,'sample_size':{'pairs':2,'single_arm_smokes':3},'money':None,'tokens':None,'causal_scope':'Intended worker-routing policy only, installed Sage in both arms. Two pairs do not establish equivalence or general quality/cost savings; outer elapsed time includes coordination/recording gaps.'})
    print(json.dumps({'gates':{a:r['gate_passed'] for a,r in allarms.items()},'pair_validator':{'exit_code':p.returncode,'stderr':p.stderr},'operational':[{'arm':a,**{k:ops(a)[k] for k in ['actor_calls','distinct_actors','followup_calls','failed_dispatch_attempts','wall_seconds']}} for a in ARMLIST],'differences':differences},indent=2))
if __name__=='__main__': main()
